&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     Si la constante no está definida, constant ahora lanza una excepción Error; anteriormente se emitía un E_WARNING y se retornaba &null;.

  &reftitle.examples;



    Uso de la función constant con constantes


<?php

define("MAXSIZE", 100);

echo MAXSIZE;
echo constant("MAXSIZE"); // idéntico a la línea anterior

interface bar {
    const test = 'foobar!';
}

class foo {
    const test = 'foobar!';
}

$const = 'test';

var_dump(constant('bar::'. $const)); // string(7) "foobar!"
var_dump(constant('foo::'. $const)); // string(7) "foobar!"

?>




    Uso de la función constant con tipos enum (a partir de PHP 8.1.0)


<?php

enum Suit
{
    case Hearts;
    case Diamonds;
    case Clubs;
    case Spades;
}

$case = 'Hearts';

var_dump(constant('Suit::'. $case)); // enum(Suit::Hearts)

?>
